import{_ as l,a0 as d,w as p,s as o,I as e,x as a,a1 as n,A as t,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"如何在 Linux 中扩展 Veritas 文件系统（VxFS） | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中扩展 Veritas 文件系统（VxFS） | LCTT (202309) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中扩展 Veritas 文件系统（VxFS） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中扩展 Veritas 文件系统（VxFS） | LCTT (202309) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202309/20230816 How to Extend Veritas File System (VxFS) in Linux","title":"如何在 Linux 中扩展 Veritas 文件系统（VxFS）","tag":"202309","desc":""},"relativePath":"202309/20230816 How to Extend Veritas File System (VxFS) in Linux.md","filePath":"[post].md"}'),h={name:"202309/20230816 How to Extend Veritas File System (VxFS) in Linux.md"};function g(k,s,c,u,x,b){const i=d("Link");return p(),o("div",null,[s[24]||(s[24]=e("h1",{id:"如何在-linux-中扩展-veritas-文件系统-vxfs",tabindex:"-1"},[a("如何在 Linux 中扩展 Veritas 文件系统（VxFS） "),e("a",{class:"header-anchor",href:"#如何在-linux-中扩展-veritas-文件系统-vxfs","aria-label":"Permalink to “如何在 Linux 中扩展 Veritas 文件系统（VxFS）”"},"​")],-1)),s[25]||(s[25]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202309/17/095154jxqizcscc3xjuzrl.jpg",alt:""})],-1)),s[26]||(s[26]=e("p",null,"扩展 VxFX 文件系统是 Linux/Unix 管理员的一项日常任务，可以通过以下文章中描述的几个步骤在线完成此任务：",-1)),s[27]||(s[27]=e("p",null,"在此，磁盘组没有足够的可用空间，因此我们将在现有磁盘组（DG）中添加新磁盘，然后调整其大小。",-1)),s[28]||(s[28]=e("p",null,[e("strong",null,"相关文章：")],-1)),e("ul",null,[e("li",null,[e("strong",null,[n(i,{href:"https://www.2daygeek.com/create-vxvm-volume-vxfs-filesystem-linux/"},{default:t(()=>[...s[0]||(s[0]=[a("如何在 Linux 中创建 VxVM 卷和文件系统",-1)])]),_:1})])]),e("li",null,[e("strong",null,[n(i,{href:"https://www.2daygeek.com/create-veritas-shared-vxfs-file-system-linux/"},{default:t(()=>[...s[1]||(s[1]=[a("如何在 Linux 上创建共享 VxFS 文件系统",-1)])]),_:1})])])]),s[29]||(s[29]=e("h3",{id:"步骤-1-识别文件系统",tabindex:"-1"},[a("步骤 1：识别文件系统 "),e("a",{class:"header-anchor",href:"#步骤-1-识别文件系统","aria-label":"Permalink to “步骤 1：识别文件系统”"},"​")],-1)),e("p",null,[s[3]||(s[3]=a("使用 ",-1)),n(i,{href:"https://www.2daygeek.com/linux-check-disk-space-usage-df-command/"},{default:t(()=>[...s[2]||(s[2]=[a("df 命令",-1)])]),_:1}),s[4]||(s[4]=a(" 检查要增加/扩展的文件系统，并记下以下输出中的磁盘组（DG）和卷名称，稍后在运行 ",-1)),s[5]||(s[5]=e("code",null,"vxdg",-1)),s[6]||(s[6]=a(" 和 ",-1)),s[7]||(s[7]=e("code",null,"vxresize",-1)),s[8]||(s[8]=a(" 命令时将使用这些名称。",-1))]),s[30]||(s[30]=r(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># df -hP /data</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Filesystem                  Size  Used Avail Use% Mounted on</span></span>
<span class="line"><span>/dev/vx/dsk/testdg/testvol  9.0G  8.4G 0.6G  95%  /data</span></span></code></pre></div><p>根据上面的输出，VxFS 文件系统大小为 9.0 GB，我们希望额外扩展 5 GB 并发布此活动，VxFS 大小将为 14 GB。</p><p>在本例中，DG 名称为 <code>testdg</code>，卷名称为 <code>testvol</code>。</p><h3 id="步骤-2-获取新磁盘-lun" tabindex="-1">步骤 2：获取新磁盘/LUN <a class="header-anchor" href="#步骤-2-获取新磁盘-lun" aria-label="Permalink to “步骤 2：获取新磁盘/LUN”">​</a></h3><p>新磁盘必须由存储团队映射到主机，这可能需要 CR 批准，因此提出 CR 并向相关团队添加必要的任务，并且还包括此活动的回滚计划。</p><h3 id="步骤-3-扫描磁盘-lun" tabindex="-1">步骤 3：扫描磁盘/LUN <a class="header-anchor" href="#步骤-3-扫描磁盘-lun" aria-label="Permalink to “步骤 3：扫描磁盘/LUN”">​</a></h3><p>存储团队将新 LUN 映射到主机后，获取 LUN id 并将其保存。</p><p>使用以下命令扫描 LUN 以在操作系统级别发现它们。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>for disk_scan in \`ls /sys/class/scsi_host\`; do </span></span>
<span class="line"><span>    echo &quot;Scanning $disk_scan…Completed&quot;</span></span>
<span class="line"><span>    echo &quot;- - -&quot; &gt; /sys/class/scsi_host/$disk_scan/scan</span></span>
<span class="line"><span>done</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Scanning host0...Completed</span></span>
<span class="line"><span>Scanning host1...Completed</span></span>
<span class="line"><span>.</span></span>
<span class="line"><span>.</span></span>
<span class="line"><span>Scanning host[N]...Completed</span></span></code></pre></div><p>扫描完成后，使用以下命令查看是否在操作系统级别找到给定的 LUN。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lsscsi --scsi | grep -i [Last_Five_Digit_of_LUN]</span></span></code></pre></div><h3 id="步骤-4-在-vxvm-中查找磁盘" tabindex="-1">步骤 4：在 VxVM 中查找磁盘 <a class="header-anchor" href="#步骤-4-在-vxvm-中查找磁盘" aria-label="Permalink to “步骤 4：在 VxVM 中查找磁盘”">​</a></h3><p>默认情况下，所有可用磁盘对 Veritas 卷管理器（VxVM）都是可见的，可以使用 <code>vxdisk</code> 命令列出这些磁盘，如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vxdisk -e list</span></span>
<span class="line"><span></span></span>
<span class="line"><span>DEVICE       TYPE           DISK        GROUP        STATUS               OS_NATIVE_NAME   ATTR</span></span>
<span class="line"><span>emc_01       auto:cdsdisk   disk1       testdg       online               sdd              -</span></span>
<span class="line"><span>emc_02       auto:cdsdisk   disk2       testdg       online               sde              -</span></span>
<span class="line"><span>emc_03       auto:none      -           -            online invalid       sdf              -</span></span>
<span class="line"><span>sda          auto:LVM       -           -            LVM                  sda              -</span></span>
<span class="line"><span>sdb          auto:LVM       -           -            LVM                  sdb              -</span></span></code></pre></div><p>磁盘 <code>sdf</code> 的状态显示为 <code>Online invalid</code> 表示该磁盘不受 VxVM 控制。但是，请使用 <code>smartctl</code> 命令仔细检查 LUN id，以确保你选择了正确的磁盘。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>smartctl -a /dev/sd[x]|grep -i unit</span></span></code></pre></div><p>如果磁盘未填充到 VxVM，请执行以下命令扫描操作系统设备树中的磁盘设备。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vxdisk scandisks</span></span></code></pre></div><h3 id="步骤-5-在-vxvm-中初始化磁盘" tabindex="-1">步骤 5：在 VxVM 中初始化磁盘 <a class="header-anchor" href="#步骤-5-在-vxvm-中初始化磁盘" aria-label="Permalink to “步骤 5：在 VxVM 中初始化磁盘”">​</a></h3><p>当磁盘在<strong>步骤 4</strong> 中对 VxVM 可见，那么使用 <code>vxdisksetup</code> 命令初始化磁盘，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vxdisksetup -i sdf</span></span></code></pre></div><p>上面的命令将磁盘 <code>sdf</code> 带到 Veritas 卷管理器（VxVM），并且磁盘状态现在更改为 <code>online</code>。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2023/07/extend-increase-vxvm-volume-vxfs-filesystem-linux-1024x201.jpg" alt=""></p><h3 id="步骤-6-将磁盘添加到-vxvm-中的磁盘组-dg" tabindex="-1">步骤 6：将磁盘添加到 VxVM 中的磁盘组（DG） <a class="header-anchor" href="#步骤-6-将磁盘添加到-vxvm-中的磁盘组-dg" aria-label="Permalink to “步骤 6：将磁盘添加到 VxVM 中的磁盘组（DG）”">​</a></h3><p><code>vxdg</code> 命令对磁盘组执行各种管理操作。在此示例中，我们将使用它向现有磁盘组（DG）添加新磁盘。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vxdg -g [DG_Name] adddisk [Any_Name_to_Disk_as_per_Your_Wish=Device_Name]</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vxdg -g testdg adddisk disk3=emc_03</span></span></code></pre></div><p>运行上述命令后，磁盘名称为 <code>disk3</code> 且磁盘组名称为 <code>testdg</code> 已针对 <code>emc_03</code> 设备进行更新 如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vxdisk -e list</span></span>
<span class="line"><span></span></span>
<span class="line"><span>DEVICE       TYPE           DISK        GROUP        STATUS               OS_NATIVE_NAME   ATTR</span></span>
<span class="line"><span>emc_01       auto:cdsdisk   disk1       testdg       online               sdd              -</span></span>
<span class="line"><span>emc_02       auto:cdsdisk   disk2       testdg       online               sde              -</span></span>
<span class="line"><span>emc_03       auto:none      disk3       testdg       online               sdf              -</span></span>
<span class="line"><span>sda          auto:LVM       -           -            LVM                  sda              -</span></span>
<span class="line"><span>sdb          auto:LVM       -           -            LVM                  sdb              -</span></span></code></pre></div><h3 id="步骤-7-检查磁盘组-dg-中的可用空间" tabindex="-1">步骤 7：检查磁盘组（DG）中的可用空间 <a class="header-anchor" href="#步骤-7-检查磁盘组-dg-中的可用空间" aria-label="Permalink to “步骤 7：检查磁盘组（DG）中的可用空间”">​</a></h3><p>要确定连接卷有多少可用空间，请运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vxassist -g testdg maxsize</span></span></code></pre></div><h3 id="步骤-8-扩展-vxvm-卷和-vxfs-文件系统" tabindex="-1">步骤 8：扩展 VxVM 卷和 VxFS 文件系统 <a class="header-anchor" href="#步骤-8-扩展-vxvm-卷和-vxfs-文件系统" aria-label="Permalink to “步骤 8：扩展 VxVM 卷和 VxFS 文件系统”">​</a></h3><p>我们为此活动添加了 5GB LUN，因此额外扩展了 VxVM 卷和 VxFS 文件系统 <code>5GB</code>，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vxresize -b -g [DG_Name] [Volume_Name] +[Size_to_be_Increased]</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vxresize -b -g testdg testvol +5g</span></span></code></pre></div><p>这里：</p><ul><li><code>vxresize</code>：命令</li><li><code>-b</code>：在后台执行调整大小操作（可选）。</li><li><code>-g</code>：将命令的操作限制为给定磁盘组，由磁盘组 ID 或磁盘组名称指定。</li><li><code>testdg</code>：我们的磁盘组（DG）名称</li><li><code>test</code>vol\`：我们的卷名称</li><li><code>+5g</code>：此卷将额外增加 5GB。</li></ul><h3 id="步骤-9-检查扩展-vxfs-文件系统" tabindex="-1">步骤 9：检查扩展 VxFS 文件系统 <a class="header-anchor" href="#步骤-9-检查扩展-vxfs-文件系统" aria-label="Permalink to “步骤 9：检查扩展 VxFS 文件系统”">​</a></h3><p>最后，使用 <code>df</code> 命令检查 <code>/data</code> 的扩展 VxFS：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># df -hP /data</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Filesystem                  Size  Used Avail Use% Mounted on</span></span>
<span class="line"><span>/dev/vx/dsk/testdg/testvol  14G   8.4G 5.6G  68%  /data</span></span></code></pre></div><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>在本教程中，我们向你展示了如何向现有磁盘组（DG）添加新磁盘，以及如何通过几个简单步骤在 Linux 中扩展 VxVM 卷和 VxFS 文件系统。</p><p>如果你有任何问题或反馈，请随时在下面发表评论。</p><p><em>（题图：MJ/3fe4fdb7-99da-4b8f-a818-0ae232e6fbcc）</em></p><hr>`,47)),e("p",null,[s[10]||(s[10]=a("via: ",-1)),n(i,{href:"https://www.2daygeek.com/extend-increase-vxvm-volume-vxfs-filesystem-linux/"},{default:t(()=>[...s[9]||(s[9]=[a("https://www.2daygeek.com/extend-increase-vxvm-volume-vxfs-filesystem-linux/",-1)])]),_:1})]),e("p",null,[s[15]||(s[15]=a("作者：",-1)),n(i,{href:"https://www.2daygeek.com/author/jayabal/"},{default:t(()=>[...s[11]||(s[11]=[a("Jayabal Thiyagarajan",-1)])]),_:1}),s[16]||(s[16]=a(" 选题：",-1)),n(i,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[12]||(s[12]=[a("lujun9972",-1)])]),_:1}),s[17]||(s[17]=a(" 译者：",-1)),n(i,{href:"https://github.com/geekpi"},{default:t(()=>[...s[13]||(s[13]=[a("geekpi",-1)])]),_:1}),s[18]||(s[18]=a(" 校对：",-1)),n(i,{href:"https://github.com/wxy"},{default:t(()=>[...s[14]||(s[14]=[a("wxy",-1)])]),_:1})]),e("p",null,[s[21]||(s[21]=a("本文由 ",-1)),n(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[19]||(s[19]=[a("LCTT",-1)])]),_:1}),s[22]||(s[22]=a(" 原创编译，",-1)),n(i,{href:"https://linux.cn/"},{default:t(()=>[...s[20]||(s[20]=[a("Linux中国",-1)])]),_:1}),s[23]||(s[23]=a(" 荣誉推出",-1))])])}const V=l(h,[["render",g]]);export{v as __pageData,V as default};
